export { AgentRun } from "./agent-run";
export { agentRunChineseLabels, agentRunEnglishLabels } from "./agent-run-labels";
export type { AgentRunControl, AgentRunLabels, AgentRunNode, AgentRunProps, AgentRunSnapshot, AgentRunStatus, AgentRunTool } from "./agent-run-types";

"use client";
import { useId, useMemo, useRef, useState, type CSSProperties } from "react";
import { Badge, type BadgeStatus } from "@ui/badge";
import { Button } from "@ui/button";
import { Card, CardContent } from "@ui/card";
import { SegmentedBar, chartColor } from "@ui/chart-primitives";
import { DropdownContent, DropdownMenu, DropdownTrigger } from "@ui/dropdown";
import { Empty, EmptyTitle } from "@ui/empty";
import { InfoItem, InfoItemContent, InfoItemDescription, InfoItemLeading, InfoItemTitle, InfoItemTrailing } from "@ui/info-item";
import { MenuItem } from "@ui/menu-item";
import { Popover, PopoverContent, PopoverTrigger } from "@ui/popover";
import { useIcon, type IconName } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { AgentRunDetails, AgentRunHandoff, AgentRunToolBadge } from "./agent-run-details";
import { agentRunEnglishLabels } from "./agent-run-labels";
import type { AgentRunLabels, AgentRunNode, AgentRunProps, AgentRunStatus } from "./agent-run-types";
import styles from "./agent-run.module.css";
const statusAppearance = {
    idle: { status: "neutral", icon: "circle" },
    working: { status: "info", icon: "circle" },
    done: { status: "success", icon: "check" },
    paused: { status: "warning", icon: "pause" },
    stopped: { status: "neutral", icon: "circle-x" },
    failed: { status: "danger", icon: "circle-x" },
} as const satisfies Record<AgentRunStatus, {
    status: BadgeStatus;
    icon: IconName;
}>;
function summarizeTree(root: AgentRunNode | null) {
    let working = 0;
    const ids = new Set<string>();
    function visit(node: AgentRunNode) {
        ids.add(node.id);
        if (node.status === "working")
            working += 1;
        node.children?.forEach(visit);
    }
    if (root)
        visit(root);
    return { working, ids };
}
interface AgentRunTreeContext {
    runId: string;
    openId: string | null;
    onOpenChange: (id: string, open: boolean) => void;
    labels: AgentRunLabels;
    locale: string;
    compactNumber: Intl.NumberFormat;
    fullNumber: Intl.NumberFormat;
    onMessage: AgentRunProps["onMessage"];
    onControl: AgentRunProps["onControl"];
}
function useAgentRunActivity(node: AgentRunNode) {
    const handoffFrom = node.handoff?.from;
    const handoffSummary = node.handoff?.summary;
    const [previous, setPrevious] = useState({ status: node.status, handoffFrom, handoffSummary, pulse: 0 });
    const handoffChanged = handoffFrom !== previous.handoffFrom || handoffSummary !== previous.handoffSummary;
    if (previous.status !== node.status || handoffChanged) {
        const started = node.status === "working" && previous.status !== "working";
        let pulse = previous.pulse;
        if (started || (handoffChanged && node.handoff))
            pulse += 1;
        setPrevious({ status: node.status, handoffFrom, handoffSummary, pulse });
    }
    return node.status === "paused" || node.status === "stopped" ? 0 : previous.pulse;
}
function AgentRunCard({ node, color, context, pulse }: {
    node: AgentRunNode;
    color: string;
    context: AgentRunTreeContext;
    pulse: number;
}) {
    const cardRef = useRef<HTMLDivElement>(null);
    const titleId = useId();
    const statusId = useId();
    const summaryId = useId();
    const compact = node.kind === "tool";
    const open = context.openId === node.id;
    const appearance = statusAppearance[node.status];
    const StatusIcon = useIcon(appearance.icon);
    const AgentIcon = useIcon(node.icon ?? (compact ? "settings" : "doc-data-grid"));
    const { labels, compactNumber, fullNumber } = context;
    const usage = node.usage;
    const hasUsage = usage && Number.isFinite(usage.tokens) && usage.tokens >= 0 && Number.isFinite(usage.limit) && usage.limit > 0;
    const nearLimit = hasUsage && usage.tokens / usage.limit >= 0.8;
    return <Popover open={open} onOpenChange={(next) => context.onOpenChange(node.id, next)}>
    <Card ref={cardRef} className={cn("relative border-hairline border-border-subtle pb-3 shadow-control transition-colors duration-fast hover:bg-hover", open && "border-border", compact ? "min-h-29" : "min-h-40")} data-agent-node={node.id} data-status={node.status}>
      <InfoItem className="px-3.5 pt-3.5 pb-0">
        <InfoItemLeading className={styles.nodeIcon} aria-hidden="true"><AgentIcon /></InfoItemLeading>
        <InfoItemContent>
          <InfoItemTitle id={titleId} className="truncate" title={node.name}>{node.name}</InfoItemTitle>
          {!compact && node.model && <InfoItemDescription className="truncate" title={node.model}>{node.model}</InfoItemDescription>}
        </InfoItemContent>
        <InfoItemTrailing>
          <Badge id={statusId} size="sm" status={appearance.status} className={cn(styles.statusBadge, compact && "min-w-5 justify-center gap-0 px-0")} leadingIcon={<span className={styles.statusEnter} key={node.status}><StatusIcon className={cn(node.status === "idle" && styles.idleIcon, node.status === "working" && cn(styles.workingIcon, "motion-safe:animate-spin"))}/></span>}>
            <span key={node.status} className={compact ? "sr-only" : styles.statusEnter}>{labels.status[node.status]}</span>
          </Badge>
        </InfoItemTrailing>
      </InfoItem>
      <CardContent className={cn("grid gap-2 px-3.5", compact ? "pt-2" : "pt-3")}>
        <InfoItemDescription id={summaryId} className="truncate" title={node.summary}>{node.summary}</InfoItemDescription>
        {hasUsage && <div className="flex items-center gap-2">
          <SegmentedBar className={cn(styles.usage, "h-1 flex-1 gap-0")} mode="capacity" total={usage.limit} segmentSlot="agent-run-usage-fill" remainderSlot="agent-run-usage-remainder" style={{ "--agent-run-usage-ratio": Math.min(1, usage.tokens / usage.limit) } as CSSProperties} valueText={`${fullNumber.format(usage.tokens)} / ${fullNumber.format(usage.limit)} ${labels.tokens}`} segments={[{ id: node.id, label: labels.tokens, value: usage.tokens, color: nearLimit ? "var(--warning-strong)" : color }]}/>
          <InfoItemDescription aria-hidden="true" className={cn("shrink-0 tabular-nums transition-colors duration-moderate motion-reduce:transition-none", nearLimit && "text-fg-warning")}>{compactNumber.format(usage.tokens)} / {compactNumber.format(usage.limit)}</InfoItemDescription>
        </div>}
        {!compact && <div className="mt-1 flex min-h-5 min-w-0 items-center gap-1.5">
          {node.tools?.slice(0, 2).map((tool) => <AgentRunToolBadge key={tool.id} tool={tool} compact/>)}
          {node.handoff && <AgentRunHandoff handoff={node.handoff} compact/>}
        </div>}
      </CardContent>
      {pulse > 0 && <span key={pulse} className={cn(styles.activityGlow, "rounded-xl")} aria-hidden="true"/>}
      <PopoverTrigger className="absolute inset-0 z-action cursor-pointer rounded-xl outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-focus-ring" aria-labelledby={`${titleId} ${statusId}`} aria-describedby={summaryId}/>
    </Card>
    <PopoverContent anchor={cardRef} side={compact ? "top" : "bottom"} align="start" sideOffset={8} surfaceShadow="overlay" className={cn(styles.details, "p-0")}>
      <div className={cn(styles.detailsBody, "grid gap-2.5 overflow-y-auto p-3.5")}>
        <AgentRunDetails node={node} runId={context.runId} labels={labels} locale={context.locale} onMessage={context.onMessage} onControl={context.onControl}/>
      </div>
    </PopoverContent>
  </Popover>;
}
function AgentRunBranch({ node, color, root = false, context }: {
    node: AgentRunNode;
    color: string;
    root?: boolean;
    context: AgentRunTreeContext;
}) {
    const resolvedColor = node.colorIndex == null ? color : chartColor(node.colorIndex);
    const children = node.children ?? [];
    const pulse = useAgentRunActivity(node);
    return <li className={root ? styles.root : styles.branch} style={{ "--agent-run-color": resolvedColor } as CSSProperties} data-active={node.status === "working"}>
    <div className={cn(styles.card, pulse > 0 && (pulse % 2 ? styles.activityOdd : styles.activityEven))}>
      <AgentRunCard node={node} color={resolvedColor} context={context} pulse={pulse}/>
    </div>
    {children.length > 0 && <ul role="list" className={cn(styles.children, root && children.length <= 3 && styles.branches)}>
      {children.map((child) => <AgentRunBranch key={child.id} node={child} color={resolvedColor} context={context}/>)}
    </ul>}
  </li>;
}
type AgentRunTreeProps = Pick<AgentRunProps, "run" | "onControl" | "onMessage"> & {
    ids: ReadonlySet<string>;
    labels: AgentRunLabels;
    locale: string;
};
function AgentRunTree({ run, ids, labels, locale, onControl, onMessage }: AgentRunTreeProps) {
    const [openId, setOpenId] = useState<string | null>(null);
    const numbers = useMemo(() => ({
        compactNumber: new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }),
        fullNumber: new Intl.NumberFormat(locale),
    }), [locale]);
    if (openId !== null && !ids.has(openId))
        setOpenId(null);
    if (!run.root)
        return <Empty scope="inline" reason="no-data"><EmptyTitle>{labels.empty}</EmptyTitle></Empty>;
    const context: AgentRunTreeContext = {
        runId: run.id,
        openId,
        onOpenChange: (id, open) => setOpenId((current) => open ? id : current === id ? null : current),
        labels,
        locale,
        ...numbers,
        onMessage,
        onControl,
    };
    return <ul role="list" className={styles.tree}><AgentRunBranch node={run.root} color={chartColor(1)} context={context} root/></ul>;
}
export function AgentRun({ run, runs, onRunChange, labels = agentRunEnglishLabels, locale = "en", onControl, onMessage, className }: AgentRunProps) {
    const titleId = useId();
    const Folder = useIcon("folder");
    const Chevron = useIcon("chevron-down");
    const { working, ids } = summarizeTree(run.root);
    return <section aria-labelledby={titleId} className={cn(styles.panel, "min-w-0 bg-surface-base p-4 sm:p-8", className)} data-block="agent-run">
    <header className="flex min-w-0 flex-wrap items-center justify-between gap-x-4 gap-y-1">
      {onRunChange && runs && runs.length > 0 ? <DropdownMenu>
        <DropdownTrigger render={<Button type="button" variant="ghost" size="md" className="min-w-0 max-w-full" leadingIcon={Folder} trailingIcon={Chevron} aria-label={`${labels.chooseRun}: ${run.title}`}/>}>
          <span id={titleId} className="truncate">{run.title}</span>
        </DropdownTrigger>
        <DropdownContent checkedIndex={runs.findIndex((candidate) => candidate.id === run.id)}>
          {runs.map((candidate, index) => <MenuItem key={candidate.id} index={index} label={candidate.title} icon={Folder} checked={run.id === candidate.id} onSelect={() => onRunChange(candidate.id)}/>)}
        </DropdownContent>
      </DropdownMenu> : <h2 id={titleId} className="flex min-w-0 items-center gap-2 text-body font-medium text-fg-default"><Folder size={16} aria-hidden="true"/><span className="wrap-anywhere">{run.title}</span></h2>}
      <p role="status" className="flex shrink-0 gap-3 text-body tabular-nums">
        <span className={working ? "text-fg-info" : "text-fg-subtle"}>{labels.workingCount(working)}</span>
        <span className="text-fg-muted">{labels.totalCount(ids.size)}</span>
      </p>
    </header>
    <AgentRunTree key={run.id} run={run} ids={ids} labels={labels} locale={locale} onControl={onControl} onMessage={onMessage}/>
  </section>;
}

"use client";
import ClaudeColor from "@lobehub/icons/es/Claude/components/Color";
import { useEffect, useMemo, useRef, useState } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Input } from "@ui/input";
import { PopoverClose, PopoverDescription, PopoverFooter, PopoverHeader, PopoverTitle } from "@ui/popover";
import { Separator } from "@ui/separator";
import { useIcon } from "@lib/icon-context";
import type { AgentRunLabels, AgentRunNode, AgentRunProps, AgentRunTool } from "./agent-run-types";
export function AgentRunToolBadge({ tool, compact }: {
    tool: AgentRunTool;
    compact?: boolean;
}) {
    const Icon = useIcon(tool.icon);
    return <Badge size="sm" leadingIcon={<Icon />} title={compact ? tool.label : undefined}>
    {compact ? <span className="sr-only">{tool.label}</span> : tool.label}
  </Badge>;
}
export function AgentRunHandoff({ handoff, compact }: {
    handoff: NonNullable<AgentRunNode["handoff"]>;
    compact?: boolean;
}) {
    const HandoffIcon = useIcon("corner-down-right");
    return <span className="flex min-w-0 items-center gap-1 text-label text-fg-muted" title={compact ? `${handoff.from} · ${handoff.summary}` : undefined}>
    <HandoffIcon className="size-3.5 shrink-0" aria-hidden="true"/>
    <span className={compact ? "truncate" : "wrap-anywhere"}><span className="font-medium">{handoff.from}</span>{" "}{handoff.summary}</span>
  </span>;
}
export function AgentRunDetails({ node, runId, labels, locale, onMessage, onControl }: {
    node: AgentRunNode;
    runId: string;
    labels: AgentRunLabels;
    locale: string;
    onMessage: AgentRunProps["onMessage"];
    onControl: AgentRunProps["onControl"];
}) {
    const [composing, setComposing] = useState(false);
    const [message, setMessage] = useState("");
    const input = useRef<HTMLInputElement>(null);
    const messageButton = useRef<HTMLButtonElement>(null);
    const Close = useIcon("x");
    const modelIcon = node.modelIcon ?? (/^claude(?:[-\s]|$)/i.test(node.model?.trim() ?? "") ? <ClaudeColor size={16}/> : undefined);
    const { number, currency } = useMemo(() => ({
        number: new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }),
        currency: new Intl.NumberFormat(locale, { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 }),
    }), [locale]);
    const canControl = onControl && node.controllable && (node.status === "working" || node.status === "paused");
    const paused = node.status === "paused";
    const metrics = [
        [labels.elapsed, node.elapsedSeconds == null ? undefined : labels.duration(number.format(node.elapsedSeconds))],
        [labels.cost, node.costUsd == null ? undefined : currency.format(node.costUsd)],
        [labels.tokens, node.usage == null ? undefined : number.format(node.usage.tokens)],
    ].filter(([, value]) => value !== undefined);
    useEffect(() => {
        if (composing)
            input.current?.focus();
    }, [composing]);
    return <>
    <PopoverHeader className="gap-1.5">
      <div className="flex items-center justify-between gap-2">
        <PopoverTitle className="wrap-anywhere">{node.name}</PopoverTitle>
        <PopoverClose render={<Button type="button" variant="ghost" size="xs" iconOnly aria-label={labels.close}><Close /></Button>}/>
      </div>
      <PopoverDescription className="wrap-anywhere">{node.assignment ?? node.summary}</PopoverDescription>
      {node.assignment && node.assignment !== node.summary && <p className="wrap-anywhere text-label text-fg-muted">{node.summary}</p>}
      {node.model && <Badge size="sm" leadingIcon={modelIcon}>{node.model}</Badge>}
    </PopoverHeader>
    {metrics.length > 0 && <>
      <Separator tone="subtle"/>
      <dl className="flex flex-wrap gap-x-5 gap-y-2 tabular-nums">
        {metrics.map(([label, value]) => <div key={label} className="min-w-0 flex-1">
          <dt className="text-label text-fg-muted">{label}</dt><dd className="font-medium">{value}</dd>
        </div>)}
      </dl>
    </>}
    {(Boolean(node.tools?.length) || node.handoff) && <>
      <Separator tone="subtle"/>
      <div className="grid gap-2">
        {Boolean(node.tools?.length) && <div className="flex flex-wrap gap-1">
          {node.tools?.map((tool) => <AgentRunToolBadge key={tool.id} tool={tool}/>)}
        </div>}
        {node.handoff && <AgentRunHandoff handoff={node.handoff}/>}
      </div>
    </>}
    {(onMessage || canControl) && <PopoverFooter className="mt-1 flex-wrap justify-start gap-1.5">
      {onMessage && <Button ref={messageButton} type="button" variant="secondary" size="lg" className="flex-1" aria-expanded={composing} onClick={() => setComposing((open) => !open)}>{labels.message}</Button>}
      {canControl && <>
        <Button type="button" variant="secondary" size="lg" className="flex-1" onClick={() => onControl(runId, node.id, paused ? "resume" : "pause")}>{paused ? labels.resume : labels.pause}</Button>
        <Button type="button" variant="secondary" size="lg" className="flex-1" onClick={() => onControl(runId, node.id, "stop")}>{labels.stop}</Button>
      </>}
    </PopoverFooter>}
    {onMessage && composing && <form className="flex gap-2" onSubmit={(event) => {
                event.preventDefault();
                const text = message.trim();
                if (!text)
                    return;
                onMessage(runId, node.id, text);
                setMessage("");
                setComposing(false);
                messageButton.current?.focus();
            }}>
      <Input ref={input} size="sm" value={message} onChange={(event) => setMessage(event.target.value)} aria-label={labels.message}/>
      <Button type="submit" size="sm" disabled={!message.trim()}>{labels.send}</Button>
    </form>}
  </>;
}

import type { ReactNode } from "react";
import type { ChartColorIndex } from "@ui/chart-primitives";
import type { IconName } from "@lib/icon-context";
export type AgentRunStatus = "idle" | "working" | "done" | "paused" | "stopped" | "failed";
export type AgentRunControl = "pause" | "resume" | "stop";
export interface AgentRunTool {
    id: string;
    label: string;
    icon: IconName;
}
export interface AgentRunNode {
    /** Stable and unique within the run. */
    id: string;
    name: string;
    status: AgentRunStatus;
    summary: string;
    assignment?: string;
    model?: string;
    /** Model logo in the details. Claude models have a default logo. */
    modelIcon?: ReactNode;
    kind?: "agent" | "tool";
    icon?: IconName;
    /** Defaults to the parent's chart color, or chart color 1 at the root. */
    colorIndex?: ChartColorIndex;
    usage?: {
        tokens: number;
        limit: number;
    };
    elapsedSeconds?: number;
    costUsd?: number;
    tools?: readonly AgentRunTool[];
    handoff?: {
        from: string;
        summary: string;
    };
    /** Enables run controls in the details when the host supplies onControl. */
    controllable?: boolean;
    children?: readonly AgentRunNode[];
}
export interface AgentRunSnapshot {
    id: string;
    title: string;
    root: AgentRunNode | null;
}
export interface AgentRunLabels {
    status: Record<AgentRunStatus, string>;
    chooseRun: string;
    close: string;
    empty: string;
    elapsed: string;
    cost: string;
    tokens: string;
    message: string;
    send: string;
    pause: string;
    resume: string;
    stop: string;
    duration: (seconds: string) => string;
    workingCount: (count: number) => string;
    totalCount: (count: number) => string;
}
export interface AgentRunProps {
    /** Replace the snapshot as activity arrives, preserving run and node IDs. */
    run: AgentRunSnapshot;
    runs?: readonly Pick<AgentRunSnapshot, "id" | "title">[];
    onRunChange?: (runId: string) => void;
    onControl?: (runId: string, nodeId: string, control: AgentRunControl) => void;
    onMessage?: (runId: string, nodeId: string, message: string) => void;
    labels?: AgentRunLabels;
    locale?: string;
    className?: string;
}

.panel {
  container-type: inline-size;
}

.tree {
  --card-width: 18rem;
  --child-indent: 1.5rem;
  --child-gap: 0.75rem;
  --elbow-width: 0.5rem;
  --edge-width: calc(3 * var(--border-width-hairline));
  margin: 1.5rem auto 0;
}

.root,
.branch,
.card {
  position: relative;
  min-inline-size: 0;
}

.card:has(+ .children)::after {
  position: absolute;
  inset-block-start: calc(100% + 0.25rem);
  inset-inline-start: calc(var(--child-indent) - var(--elbow-width));
  z-index: var(--layer-indicator);
  inline-size: 0.5rem;
  block-size: 0.5rem;
  border: var(--edge-width) solid color-mix(in oklab, var(--agent-run-color) 46%, var(--surface-base));
  border-radius: 50%;
  background: var(--surface-base);
  content: "";
  translate: -50% -50%;
  pointer-events: none;
}

.card:dir(rtl)::after {
  translate: 50% -50%;
}

.nodeIcon {
  background-color: color-mix(in oklab, var(--agent-run-color) 8%, var(--surface-base));
  color: var(--agent-run-color);
}

.idleIcon {
  scale: 0.35;
  fill: currentColor;
}

.workingIcon circle {
  stroke-dasharray: 45 18;
}

.statusBadge {
  transition: background-color var(--motion-duration-moderate),
    border-color var(--motion-duration-moderate), color var(--motion-duration-moderate);
}

.statusEnter {
  display: inline-flex;
  animation: status-in var(--motion-duration-moderate) var(--ease-out, ease-out) both;
}

@keyframes status-in {
  from { opacity: 0; translate: 0 2px; }
  to { opacity: 1; translate: 0; }
}

.usage {
  position: relative;
  background-color: var(--muted);
}

/* Keep SegmentedBar's capacity semantics and animate its supplied fill slot. */
.usage > [data-slot="agent-run-usage-fill"] {
  display: block;
  position: absolute;
  inset: 0;
  transform: scaleX(var(--agent-run-usage-ratio));
  transform-origin: left center;
  transition: transform var(--motion-duration-slow) var(--ease-out, ease-out),
    background-color var(--motion-duration-moderate);
}

.usage:dir(rtl) > [data-slot="agent-run-usage-fill"] {
  transform-origin: right center;
}

.usage > [data-slot="agent-run-usage-remainder"] {
  visibility: hidden;
}

.details {
  inline-size: var(--anchor-width, 18rem);
  min-inline-size: min(16rem, calc(100vw - 1.5rem));
  max-inline-size: calc(100vw - 1.5rem);
}

.detailsBody {
  max-block-size: min(var(--available-height, 100dvh), calc(100dvh - 1.5rem));
  overscroll-behavior: contain;
}

.children {
  --edge-color: color-mix(in oklab, var(--agent-run-color) 32%, var(--surface-base));
  --active-edge-color: color-mix(in oklab, var(--agent-run-color) 58%, var(--surface-base));
  --edge-pulse-color: color-mix(in oklab, var(--agent-run-color) 88%, var(--surface-base));
  padding-block-start: var(--child-gap);
  padding-inline-start: var(--child-indent);
}

.children > .branch + .branch {
  margin-block-start: var(--child-gap);
}

.branch {
  --incoming-edge: var(--edge-color);
}

.branch[data-active="true"] {
  --incoming-edge: var(--active-edge-color);
}

.branch:has(> .activityOdd)::before,
.branch:has(> .activityOdd)::after,
.root:has(> .activityOdd) > .branches::before {
  animation: edge-pulse var(--motion-duration-slow) var(--ease-out, ease-out);
}

.branch:has(> .activityEven)::before,
.branch:has(> .activityEven)::after,
.root:has(> .activityEven) > .branches::before {
  animation: edge-pulse-next var(--motion-duration-slow) var(--ease-out, ease-out);
}

.activityOdd,
.activityEven {
  --activity-color: color-mix(in oklab, var(--agent-run-color) 18%, transparent);
}

.activityGlow {
  position: absolute;
  z-index: var(--layer-decoration);
  inset: 0;
  background: linear-gradient(to bottom, transparent 60%, var(--activity-color));
  pointer-events: none;
  animation: activity-glow var(--motion-duration-slow) var(--ease-out, ease-out) both;
}

@keyframes activity-glow {
  0%, 100% { opacity: 0; }
  30% { opacity: 1; }
}

@keyframes edge-pulse {
  45% { border-color: var(--edge-pulse-color); }
}

/* The alternate keyframe lets consecutive handoffs restart on the same node. */
@keyframes edge-pulse-next {
  45% { border-color: var(--edge-pulse-color); }
}

.children > .branch::before,
.children > .branch:not(:last-child)::after {
  position: absolute;
  inset-inline-start: calc(-1 * var(--elbow-width));
  inline-size: var(--elbow-width);
  border-inline-start: var(--edge-width) solid var(--incoming-edge);
  content: "";
  pointer-events: none;
  transition: border-color var(--motion-duration-moderate) var(--ease-out, ease-out);
}

.children > .branch::before {
  inset-block-start: calc(-1 * var(--child-gap));
  block-size: calc(var(--child-gap) + var(--control-height-md));
  border-block-end: var(--edge-width) solid var(--incoming-edge);
  border-end-start-radius: 0.375rem;
}

.children > .branch:not(:last-child)::after {
  inset-block: calc(var(--control-height-md) - 0.375rem) 0;
}

.children > .branch:has(~ [data-active="true"])::before,
.children > .branch:has(~ [data-active="true"])::after {
  border-inline-start-color: var(--active-edge-color);
}

@container (min-width: 52rem) {
  .tree {
    --child-indent: 2.375rem;
    --column-padding: clamp(1rem, 2.3cqi, 1.5rem);
    --fan-gap: 3.375rem;
    --fan-leg: 1.625rem;
    --junction-radius: 0.625rem;
    padding-inline-end: 2rem;
  }

  .root:has(> .branches) > .card {
    inline-size: var(--card-width);
    margin-inline: auto;
  }

  .root:has(> .branches) > .card::after {
    inset-inline-start: 50%;
  }

  .branches {
    --fan-extension: 0px;
    position: relative;
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(0, calc(var(--card-width) + 2 * var(--column-padding)));
    justify-content: center;
    padding-block-start: var(--fan-gap);
    padding-inline-start: 0;
  }

  .branches:has(> :nth-child(3)) {
    --fan-extension: 50%;
  }

  .branches::before {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 50%;
    block-size: calc(var(--fan-gap) - var(--fan-leg));
    border-inline-start: var(--edge-width) solid var(--edge-color);
    content: "";
    pointer-events: none;
    transition: border-color var(--motion-duration-moderate) var(--ease-out, ease-out);
  }

  .children.branches > .branch {
    padding-inline: var(--column-padding);
    margin-block-start: 0;
  }

  .branches > .branch > .children {
    /* Nested cards use the column gutter as part of their indentation. */
    margin-inline-end: calc(-1 * var(--child-indent));
  }

  .children.branches > .branch::before,
  .children.branches > .branch:not(:last-child)::after {
    inset: auto;
    inline-size: auto;
    border: 0;
    border-radius: 0;
  }

  .children.branches > .branch::before {
    inset-block-start: calc(-1 * var(--fan-leg));
    block-size: var(--fan-leg);
    border-block-start: var(--edge-width) solid var(--incoming-edge);
  }

  .children.branches > .branch:first-child::before {
    inset-inline: 50% calc(var(--junction-radius) - var(--fan-extension));
    border-inline-start: var(--edge-width) solid var(--incoming-edge);
    border-start-start-radius: var(--junction-radius);
  }

  .children.branches > .branch:last-child::before {
    inset-inline: calc(var(--junction-radius) - var(--fan-extension)) 50%;
    border-inline-end: var(--edge-width) solid var(--incoming-edge);
    border-start-end-radius: var(--junction-radius);
  }

  /* The outer legs curve into the root stem at the center of the fan. */
  .children.branches > .branch:not(:only-child):is(:first-child, :last-child)::after {
    position: absolute;
    inset-block: auto calc(100% + var(--fan-leg) - var(--edge-width));
    inline-size: calc(var(--junction-radius) + var(--edge-width));
    block-size: var(--junction-radius);
    border: 0;
    border-block-end: var(--edge-width) solid var(--incoming-edge);
    content: "";
    pointer-events: none;
    transition: border-color var(--motion-duration-moderate) var(--ease-out, ease-out);
  }

  .children.branches > .branch:first-child:not(:only-child)::after {
    inset-inline: auto calc(-1 * (var(--fan-extension) + var(--edge-width)));
    border-inline-end: var(--edge-width) solid var(--incoming-edge);
    border-end-end-radius: var(--junction-radius);
  }

  .children.branches > .branch:last-child:not(:only-child)::after {
    inset-inline: calc(-1 * var(--fan-extension)) auto;
    border-inline-start: var(--edge-width) solid var(--incoming-edge);
    border-end-start-radius: var(--junction-radius);
  }

  .children.branches > .branch:is(:only-child, :not(:first-child, :last-child))::before {
    inset-inline: 50% auto;
    border: 0;
    border-inline-start: var(--edge-width) solid var(--incoming-edge);
  }
}

@media (prefers-reduced-motion: reduce) {
  .statusEnter,
  .activityGlow,
  .branch:has(> :is(.activityOdd, .activityEven))::before,
  .branch:has(> :is(.activityOdd, .activityEven))::after,
  .root:has(> :is(.activityOdd, .activityEven)) > .branches::before {
    animation: none;
  }

  .statusBadge,
  .usage > [data-slot="agent-run-usage-fill"],
  .children::before,
  .children > .branch::before,
  .children > .branch::after {
    transition: none;
  }

  .activityGlow {
    display: none;
  }
}

